class Solution {
    public List<List<String>> printTree(TreeNode root) {
        int height = getHeight(root);
        int m = height + 1;
        int n = (1 << m) - 1;
        List<List<String>> res = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            List<String> row = new ArrayList<>();
            for (int j = 0; j < n; j++) row.add("");
            res.add(row);
        }
        fill(root, 0, (n - 1) / 2, height, res);
        return res;
    }

    private int getHeight(TreeNode node) {
        if (node == null) return -1;
        return 1 + Math.max(getHeight(node.left), getHeight(node.right));
    }

    private void fill(TreeNode node, int r, int c, int height, List<List<String>> res) {
        if (node == null) return;
        res.get(r).set(c, String.valueOf(node.val));
        int offset = (height - r - 1 >= 0) ? (1 << (height - r - 1)) : 0;
        if (node.left != null) fill(node.left, r + 1, c - offset, height, res);
        if (node.right != null) fill(node.right, r + 1, c + offset, height, res);
    }
}

var printTree = function(root) {
    function getHeight(node) {
        if (!node) return -1;
        return 1 + Math.max(getHeight(node.left), getHeight(node.right));
    }

    const height = getHeight(root);
    const m = height + 1;
    const n = (1 << m) - 1;
    const res = Array.from({ length: m }, () => Array(n).fill(""));

    function fill(node, r, c) {
        if (!node) return;
        res[r][c] = String(node.val);
        const offset = (height - r - 1 >= 0) ? (1 << (height - r - 1)) : 0;
        if (node.left) fill(node.left, r + 1, c - offset);
        if (node.right) fill(node.right, r + 1, c + offset);
    }

    fill(root, 0, (n - 1) >> 1);
    return res;
};
